Get-VM | select -Property Name, PowerState, @{N="Cluster";E={Get-Cluster -VM $_}}, @{N="Configured OS";E={(Get-View $_).Config.GuestFullName}},  @{N="Running OS";E={(Get-View $_).Guest.GuestFullName}},@{Name="ToolsVersion";Expression={$_.ExtensionData.Guest.ToolsVersion}},@{Name="ToolsStatus";Expression={$_.ExtensionData.Guest.ToolsVersionStatus}} | Export-Csv ".\Stats_VMtools_OS\VMtools_OS_stats.csv"
